import test from 'node:test';
import assert from 'node:assert/strict';
import { canonicalURL, summarize, signature, validSignature, downloadArgs, safeError } from '../backend/server.mjs';
import handler from '../api/softload.js';

test('YouTube URLs are normalized; other hosts, credentials and command injection are rejected', () => {
  for (const input of ['https://youtu.be/abcdefghijk?t=3', 'https://www.youtube.com/watch?v=abcdefghijk&list=abc', 'https://m.youtube.com/shorts/abcdefghijk']) assert.equal(canonicalURL(input), 'https://www.youtube.com/watch?v=abcdefghijk');
  for (const input of ['https://youtube.com.evil.test/watch?v=abcdefghijk', 'http://127.0.0.1/watch?v=abcdefghijk', 'https://user@youtube.com/watch?v=abcdefghijk', 'file:///etc/passwd', '--exec rm', 'https://youtube.com:8080/watch?v=abcdefghijk']) assert.throws(() => canonicalURL(input));
});
test('Metadata only offers available MP4 qualities and real size estimates', () => {
  const result = summarize({ id: 'abcdefghijk', title: 'Demo', duration: 60, formats: [
    { ext: 'mp4', height: 720, vcodec: 'avc1', acodec: 'none', filesize: 100 },
    { ext: 'webm', height: 1080, vcodec: 'vp9' },
    { ext: 'm4a', vcodec: 'none', abr: 128, filesize: 20 }
  ] }, 1800);
  assert.deepEqual(result.qualities, [{ height: 720, bytes: 120 }]);
  assert.throws(() => summarize({ is_live: true }, 1800));
  assert.throws(() => summarize({ duration: 2000 }, 1800));
});
test('Signed download URLs reject modifications, expiry and excessive lifetimes', () => {
  const secret = 'x'.repeat(40), id = 'a'.repeat(32), expires = 1200;
  const sig = signature(secret, id, expires);
  assert.ok(validSignature(secret, id, expires, sig, 1000));
  assert.ok(!validSignature(secret, 'b'.repeat(32), expires, sig, 1000));
  assert.ok(!validSignature(secret, id, expires, sig, 1201));
  assert.ok(!validSignature(secret, id, expires, sig, 800));
});
test('Download command caps quality, selects the format, and isolates the URL', () => {
  const args = downloadArgs('https://youtu.be/abcdefghijk', 'MP4', 720, '/data/job', 10000);
  assert.ok(args.includes('--merge-output-format'));
  assert.ok(args.some(x => x.includes('height<=720')));
  assert.equal(args.at(-2), '--');
  const audio = downloadArgs('https://youtu.be/abcdefghijk', 'MP3', 720, '/data/job', 10000);
  assert.ok(audio.includes('mp3')); assert.ok(audio.includes('192K'));
  assert.throws(() => downloadArgs('https://youtu.be/abcdefghijk', 'exe', 720, '/data', 10000));
});
test('Provider failures become understandable messages', () => {
  assert.match(safeError('HTTP Error 403'), /membatasi/);
  assert.match(safeError('timeout'), /waktu/);
});
function response() { return { headers: {}, setHeader(k, v) { this.headers[k] = v; }, end(value) { this.body = value; } }; }
test('Vercel proxy keeps the secret server-side and redirects downloads without buffering them', async () => {
  process.env.BACKEND_URL = 'https://api.example.com';
  process.env.BACKEND_SECRET = 'z'.repeat(40);
  const previous = globalThis.fetch;
  try {
    globalThis.fetch = async (url, options) => {
      assert.equal(options.headers.Authorization, 'Bearer ' + 'z'.repeat(40));
      assert.equal(url.pathname, '/jobs/' + 'a'.repeat(32) + '/link');
      return { ok: true, status: 200, json: async () => ({ url: 'https://api.example.com/files/' + 'a'.repeat(32) + '?expires=123&sig=test' }) };
    };
    const res = response();
    await handler({ method: 'GET', query: { op: 'file', id: 'a'.repeat(32) }, headers: {} }, res);
    assert.equal(res.statusCode, 302);
    assert.match(res.headers.Location, /^https:\/\/api.example.com\/files\//);
    assert.equal(res.body, undefined);
  } finally { globalThis.fetch = previous; delete process.env.BACKEND_URL; delete process.env.BACKEND_SECRET; }
});
test('Vercel proxy rejects cross-site mutations and missing server configuration', async () => {
  let res = response();
  await handler({ method: 'POST', query: { op: 'create' }, headers: {} }, res);
  assert.equal(res.statusCode, 403);
  res = response();
  await handler({ method: 'GET', query: { op: 'health' }, headers: {} }, res);
  assert.equal(res.statusCode, 503);
});

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     